{
        return Task.Run(() =>
        {
            var result = new List<SoftwarePartController>();

            var controllerActionDescriptors = _actionDescriptorCollectionProvider.ActionDescriptors.Items.OfType<ControllerActionDescriptor>().ToList();

            foreach (var item in controllerActionDescriptors)
            {
                var attribute = item.ControllerTypeInfo.GetCustomAttributes(typeof(SoftwarePartControllerOptionAttribute), false).FirstOrDefault() as SoftwarePartControllerOptionAttribute;
                result.Add(new SoftwarePartController
                {
                    Module = attribute?.Module,
                    Service = attribute?.Service,
                    Name = item.ControllerName,
                    ApplicationPartType = SoftwarePartType.Controller,
                });
            }

            result = result.DistinctBy(c => c.Name).GroupJoin(controllerActionDescriptors, c => c.Name, a => a.ControllerName, (c, a) => new SoftwarePartController
            {
                Module = c.Module,
                Service = c.Service,
                Name = c.Name,
                ApplicationPartType = SoftwarePartType.Controller,
                Actions = a.Select(b => new SoftwarePartAction
                {
                    Name = b.ActionName,
                    ApplicationPartType = SoftwarePartType.Action
                }).DistinctBy(c => c.Name).ToList()
            }).ToList();

            return result;
        });
    }

{
        if (string.IsNullOrWhiteSpace(softwareName))
            throw new ArgumentNullException(nameof(softwareName));

        var application = new SoftwarePart
        {
            Name = softwareName,
            SoftwarePartType = SoftwarePartType.Sample
        };

        var controllers = await _controllersAndActionDetector.Detect();

        foreach (var controller in controllers)
        {
            if (controller.Module is null)
            {
                if (controller.Service is null)
                {
                    AddControllerAndActionsToParent(application, controller);
                }
                else
                {
                    var service = application.Children.FirstOrDefault(c => c.Name == controller.Service && c.SoftwarePartType == SoftwarePartType.Service);
                    if (service is not null)
                    {
                        AddControllerAndActionsToParent(service, controller);
                    }
                    else
                    {
                        service = new SoftwarePart()
                        {
                            Name = controller.Service,
                            SoftwarePartType = SoftwarePartType.Service,
                        };

                        AddControllerAndActionsToParent(service, controller);

                        application.Children.Add(service);
                    }
                }
            }
            else
            {
                AddControllerAndActionsToCustomModuleAndCustomService(application, controller);
            }
        }

        return application;
    }

{
        if (string.IsNullOrEmpty(moduleName))
            return await Detect(softwareName);

        var application = new SoftwarePart
        {
            Name = softwareName,
            SoftwarePartType = SoftwarePartType.Sample,
            Children = new List<SoftwarePart>
            {
                new SoftwarePart
                {
                    Name = moduleName,
                    SoftwarePartType=SoftwarePartType.Module,
                }
            }
        };

        var controllers = await _controllersAndActionDetector.Detect();

        foreach (var controller in controllers)
        {
            if (controller.Module is null)
            {
                var module = application.Children.First(c => c.Name == moduleName);

                if (controller.Service is null)
                {
                    AddControllerAndActionsToParent(module, controller);
                }
                else
                {
                    var service = module.Children.FirstOrDefault(c => c.Name == controller.Service);
                    if (service is not null)
                    {
                        AddControllerAndActionsToParent(service, controller);
                    }
                    else
                    {
                        service = CreateSoftwarePartService(controller.Service);

                        AddControllerAndActionsToParent(service, controller);

                        module.Children.Add(service);
                    }
                }

            }
            else
            {
                AddControllerAndActionsToCustomModuleAndCustomService(application, controller);
            }
        }

        return application;
    }

